#!/usr/bin/env python3
import pathlib,json,subprocess,sys,os,hashlib
root=pathlib.Path(__file__).resolve().parents[1];binary=pathlib.Path(sys.argv[1]).resolve();helm=pathlib.Path(sys.argv[2]).resolve();out=pathlib.Path(os.environ.get('CD_AUDIT_OUTPUT',str(root/'artifacts/helm')));out.mkdir(parents=True,exist_ok=True);workspace=out/'workspace';chart=workspace/'chart';(chart/'templates').mkdir(parents=True,exist_ok=True);(workspace/'.argocd-ls.yaml').write_text('schemaVersion: 1\ntargetVersion: "3.0.0"\n');(chart/'Chart.yaml').write_text('apiVersion: v2\nname: argocd-e2e\nversion: 0.1.0\n');(chart/'values.yaml').write_text('project: 42\n');(chart/'templates/app.yaml').write_text('apiVersion: argoproj.io/v1alpha1\nkind: Application\nmetadata:\n  name: {{ .Release.Name }}\nspec:\n  project: {{ .Values.project }}\n  source:\n    repoURL: https://example.org/repo\n  destination:\n    server: https://kubernetes.default.svc\n    namespace: {{ .Release.Namespace }}\n');generated=out/'generated';cmd=[str(binary),'render-check','--root',str(workspace),'--chart',str(chart),'--helm-binary',str(helm),'--output',str(generated),'--format','json'];p=subprocess.run(cmd,capture_output=True,timeout=45);(out/'stdout').write_bytes(p.stdout);(out/'stderr').write_bytes(p.stderr);errors=[]
try:
 r=json.loads(p.stdout);assert p.returncode==1 and r['analysisComplete']==True
 d=next(d for d in r['diagnostics'] if d['code']=='SCHEMA_TYPE');assert d['uri']==(generated/'generated.yaml').as_uri() and d['range']['start']['line']==7
 assert r['renderer']['version'].startswith('v3.19.0') and r['renderer']['releaseName']=='argo-ls' and r['renderer']['namespace']=='default'
 assert '# Source: argocd-e2e/templates/app.yaml' in (generated/'generated.yaml').read_text()
 assert (chart/'values.yaml').read_text()=='project: 42\n'
except Exception as e:errors.append(repr(e))
(out/'results.json').write_text(json.dumps({'command':cmd,'exit':p.returncode,'expected':{'diagnostic':'SCHEMA_TYPE','generatedLine':7,'sourceUnchanged':True,'analysisComplete':True},'errors':errors,'passed':not errors},indent=2)+'\n');(out/'manifest.json').write_text(json.dumps({'command':cmd,'binarySHA256':hashlib.sha256(binary.read_bytes()).hexdigest(),'helmSHA256':hashlib.sha256(helm.read_bytes()).hexdigest(),'testSHA256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest(),'inputs':{str(p.relative_to(out)):hashlib.sha256(p.read_bytes()).hexdigest() for p in workspace.rglob('*') if p.is_file()},'generatedSHA256':hashlib.sha256((generated/'generated.yaml').read_bytes()).hexdigest() if (generated/'generated.yaml').exists() else None},indent=2)+'\n');print(json.dumps({'passed':not errors,'errors':errors}));sys.exit(0 if not errors else 1)
